<?php if($user['role']!=='customer')return;$claim=row('SELECT p.* FROM promo_codes p JOIN welcome_email_claims w ON w.promo_id=p.id WHERE w.email_key=?',[promo_email_key($user['email'])]); ?>
<section class="panel welcome-account"><h2>Your welcome code</h2><?php if(empty($_SESSION['welcome_verified'][promo_email_key($user['email'])])||!welcome_email_verified(promo_email_key($user['email']))): ?><p>Verify your email through the welcome page before viewing or using your welcome code.</p><a class="button" href="/welcome">Verify my email</a><?php elseif(!$claim): ?><p>Claim your welcome offer with just your email. Creating an account is optional.</p><a class="button" href="/welcome">Get my welcome code</a><?php else:$usage=promo_counts($claim['id']); ?><p>Status: <?= e($usage['redeemed']+$usage['legacy']>0?'Redeemed':($usage['reserved']?'Reserved by pending order':promo_status($claim))) ?></p><label>Your code<input readonly value="<?= e($claim['code']) ?>"></label><p><?= (int)$claim['discount_value'] ?>% off eligible full-priced pieces. Expires <?= e(welcome_expiry_label($claim['ends_at'])) ?>.</p><p>Apply at checkout with this account’s email. An unpaid order reserves the code until completed, paid or cancelled. Successful redemptions remain in history.</p><?php endif ?></section>
